export function renderer(canvas,options={}){
const gl=canvas.getContext('webgl',{alpha:false,preserveDrawingBuffer:!!options.preserve});if(!gl)return null;
function shader(type,source){let s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s}
let vs=shader(gl.VERTEX_SHADER,'attribute vec2 p;varying vec2 uv;void main(){uv=(p+1.)*.5;gl_Position=vec4(p,0.,1.);}');
let fs=shader(gl.FRAGMENT_SHADER,`precision mediump float;varying vec2 uv;uniform sampler2D tex;uniform vec4 crop;uniform float exposure,contrast,highlights,shadows,whites,blacks,temperature,tint,saturation,vibrance;void main(){vec2 q=vec2(uv.x,1.-uv.y);vec3 v=texture2D(tex,crop.xy+q*crop.zw).rgb;vec3 o=v;v=(v*pow(2.,exposure)-.5)*(1.+contrast/150.)+.5;v+=shadows/400.*pow(1.-o,vec3(2.))+highlights/400.*pow(o,vec3(2.))+whites/500.*pow(o,vec3(4.))+blacks/500.*pow(1.-o,vec3(4.));v+=vec3(temperature/400.+tint/800.,-tint/400.,-temperature/400.+tint/800.);v=clamp(v,0.,1.);float l=dot(v,vec3(.299,.587,.114));v=mix(vec3(l),v,1.+saturation/100.);float mx=max(v.r,max(v.g,v.b)),mn=min(v.r,min(v.g,v.b));v=mix(vec3(l),v,1.+vibrance/100.*(1.-(mx-mn)));gl_FragColor=vec4(clamp(v,0.,1.),1.);}`);
let p=gl.createProgram();gl.attachShader(p,vs);gl.attachShader(p,fs);gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error('Preview shader failed');gl.useProgram(p);let b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);let a=gl.getAttribLocation(p,'p');gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,2,gl.FLOAT,false,0,0);let tex=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tex);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
return{draw(video,c,aspect,compare=false){if(gl.isContextLost())throw Error('GPU接続が失われました。解像度を下げて再試行してください。');if(video.readyState!==undefined&&video.readyState<2)return;let sw=video.videoWidth||video.width,sh=video.videoHeight||video.height,ar=aspect==='Original'?sw/sh:aspect.split(':').map(Number).reduce((a,b)=>a/b);let ow=ar>=1?Math.min(1280,sw):Math.min(720,sw),oh=ow/ar;if(options.width){ow=options.width;oh=options.height}if(canvas.width!==Math.round(ow))canvas.width=Math.round(ow);if(canvas.height!==Math.round(oh))canvas.height=Math.round(oh);gl.viewport(0,0,canvas.width,canvas.height);let cw=Math.min(sw,sh*ar)/(c.scale||1),ch=Math.min(sh,sw/ar)/(c.scale||1);gl.uniform4f(gl.getUniformLocation(p,'crop'),(sw-cw)*(c.x??.5)/sw,(sh-ch)*(c.y??.5)/sh,cw/sw,ch/sh);for(let[k,v]of Object.entries(c.color||{})){gl.uniform1f(gl.getUniformLocation(p,k),compare?0:v)}gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,video);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);if(options.preserve&&gl.getError()!==gl.NO_ERROR)throw Error('GPUでフレームを描画できませんでした。')},black(){gl.clearColor(0,0,0,1);gl.clear(gl.COLOR_BUFFER_BIT)},dispose(){gl.deleteTexture(tex);gl.deleteBuffer(b);gl.deleteProgram(p);gl.deleteShader(vs);gl.deleteShader(fs)}}}
